package com.zafiro.wxentry.kernel;
import java.io.*;import java.util.*;

public final class SnsScheduleEngineTest {
    static int checks;static final String OWNER="wxid_schedule_owner";static long now=1800000000000L;
    interface Op {void run()throws Exception;}
    static void ok(boolean value){checks++;if(!value)throw new AssertionError("check "+checks);}
    static void rejects(Op op){boolean failed=false;try{op.run();}catch(Exception e){failed=true;}ok(failed);}
    static SnsScheduleData data(){SnsScheduleData d=new SnsScheduleData(OWNER);d.enabled=true;d.tasks.add(new SnsScheduleData.Task("1234567890abcdef1234567890abcdef",OWNER,"hello\r\n\n\nworld",now,false,now-1000));return d;}
    public static void main(String[] args)throws Exception{
        for(boolean enabled:new boolean[]{false,true})for(boolean vip:new boolean[]{false,true})for(boolean timer:new boolean[]{false,true})for(boolean continuous:new boolean[]{false,true})for(long delay:new long[]{-1,0,1,44999,45000,45001,86400000}){
            SnsScheduleData d=data();d.enabled=enabled;boolean expected=enabled&&vip&&timer&&continuous&&delay>=0&&delay<=45000;ok(SnsScheduleData.eligible(d.tasks.get(0),now+delay,enabled,vip,timer,continuous)==expected);
        }
        for(boolean timer:new boolean[]{false,true})for(boolean continuous:new boolean[]{false,true})for(boolean enabled:new boolean[]{false,true}){
            SnsScheduleData d=data();d.enabled=enabled;SnsScheduleEngine.recover(d,now,timer,continuous,false);ok(d.tasks.get(0).state==(timer&&continuous&&enabled?SnsScheduleData.State.WAITING:SnsScheduleData.State.MISSED));
        }
        SnsScheduleData d=data();String id=d.tasks.get(0).id;SnsScheduleEngine.claim(d,id,now,false);ok(d.tasks.get(0).state==SnsScheduleData.State.CLAIMED);final SnsScheduleData claimed=d;rejects(()->SnsScheduleEngine.claim(claimed,id,now,false));rejects(()->SnsScheduleEngine.claim(claimed,id,now,true));
        byte[] durable=d.encode();SnsScheduleData recovered=SnsScheduleData.decode(OWNER,durable);SnsScheduleEngine.recover(recovered,now+1,false,false,false);ok(recovered.tasks.get(0).state==SnsScheduleData.State.UNKNOWN);rejects(()->SnsScheduleEngine.claim(recovered,id,now+1,true));
        SnsScheduleEngine.recover(d,now+1,false,false,true);ok(d.tasks.get(0).state==SnsScheduleData.State.CLAIMED);d.enabled=false;final SnsScheduleData paused=d;rejects(()->SnsScheduleEngine.attach(paused,id,"client-1",false));d.enabled=true;SnsScheduleEngine.attach(d,id,"client-1",false);rejects(()->SnsScheduleEngine.queued(paused,id,"different",1,now));rejects(()->SnsScheduleEngine.queued(paused,id,"client-1",0,now));SnsScheduleEngine.queued(d,id,"client-1",42,now);
        SnsScheduleEngine.recover(d,now+999999,false,false,false);ok(d.tasks.get(0).state==SnsScheduleData.State.UPLOADING);rejects(()->SnsScheduleEngine.claim(paused,id,now,true));rejects(()->SnsScheduleEngine.result(paused,id,"client-1",43,123,now));rejects(()->SnsScheduleEngine.result(paused,id,"wrong",42,123,now));rejects(()->SnsScheduleEngine.result(paused,id,"client-1",42,0,now));SnsScheduleEngine.result(d,id,"client-1",42,123,now);ok(d.tasks.get(0).state==SnsScheduleData.State.PUBLISHED&&d.tasks.get(0).serverId==123);rejects(()->SnsScheduleEngine.claim(paused,id,now,true));
        SnsScheduleData missed=data();SnsScheduleEngine.recover(missed,now+3600000,false,false,false);missed.enabled=false;SnsScheduleEngine.claim(missed,id,now+3600000,true);SnsScheduleEngine.attach(missed,id,"manual",true);SnsScheduleEngine.queued(missed,id,"manual",7,now);SnsScheduleEngine.result(missed,id,"manual",7,-1,now);ok(missed.tasks.get(0).state==SnsScheduleData.State.FAILED);
        SnsScheduleData future=data();future.tasks.get(0).due=now+1;SnsScheduleEngine.recover(future,now,false,false,false);ok(future.tasks.get(0).state==SnsScheduleData.State.WAITING);rejects(()->SnsScheduleEngine.claim(future,id,now,false));rejects(()->SnsScheduleEngine.claim(future,id,now+45002,false));
        for(SnsScheduleData.State state:SnsScheduleData.State.values())for(int photoCount:new int[]{0,1,3,9}){
            SnsScheduleData q=data();SnsScheduleData.Task t=q.tasks.get(0);t.state=state;t.selfOnly=true;t.client="native-id";t.localId=2;t.message="中文备注";for(int i=0;i<photoCount;i++)t.photos.add(new SnsScheduleData.Photo(String.format(Locale.ROOT,"%02d.image",i),String.join("",Collections.nCopies(64,"a")),100+i));byte[] b=q.encode();SnsScheduleData decoded=SnsScheduleData.decode(OWNER,b);ok(Arrays.equals(b,decoded.encode()));ok(decoded.tasks.get(0).photos.size()==photoCount);ok(decoded.tasks.get(0).selfOnly);ok(decoded.tasks.get(0).text.equals("hello\n\nworld"));rejects(()->SnsScheduleData.decode("other_owner",b));for(int cut:new int[]{0,1,b.length-1}){final byte[] shortBytes=Arrays.copyOf(b,cut);rejects(()->SnsScheduleData.decode(OWNER,shortBytes));}byte[] trailing=Arrays.copyOf(b,b.length+1);rejects(()->SnsScheduleData.decode(OWNER,trailing));
        }
        SnsScheduleData duplicate=data();duplicate.tasks.add(duplicate.tasks.get(0));rejects(()->duplicate.encode());SnsScheduleData foreign=data();foreign.tasks.add(new SnsScheduleData.Task("abcdefabcdefabcdefabcdefabcdefab","another_owner","foreign",now,true,now));rejects(()->foreign.encode());
        rejects(()->new SnsScheduleData.Photo("../01.image",String.join("",Collections.nCopies(64,"a")),1));rejects(()->new SnsScheduleData.Photo("00.image","invalid",1));rejects(()->new SnsScheduleData.Photo("00.image",String.join("",Collections.nCopies(64,"a")),33L*1024*1024));
        ok(SnsScheduleEngine.commitTimely(now,now,5000,now+1000,6000));ok(!SnsScheduleEngine.commitTimely(now,now,5000,now+45001,50001));ok(!SnsScheduleEngine.commitTimely(now,now,5000,now+1000,70001));ok(!SnsScheduleEngine.commitTimely(now,now,5000,now-1,6000));ok(!SnsScheduleEngine.commitTimely(now,now,5000,now+1000,4000));ok(!SnsScheduleEngine.commitTimely(now,now,5000,now+40000,6000));
        SnsScheduleData uncertain=data();SnsScheduleEngine.claim(uncertain,id,now,false);SnsScheduleEngine.attach(uncertain,id,"owned-client",false);SnsScheduleEngine.queued(uncertain,id,"owned-client",51,now);uncertain.find(id).state=SnsScheduleData.State.UNKNOWN;SnsScheduleEngine.result(uncertain,id,"owned-client",51,991,now);ok(uncertain.find(id).state==SnsScheduleData.State.PUBLISHED);
        for(long gap:new long[]{0,10000,180000,197000,600000,86400000})ok(SnsScheduleEngine.sameClock(true,now,5000,now+gap,5000+gap));ok(!SnsScheduleEngine.sameClock(false,now,5000,now+180000,185000));ok(!SnsScheduleEngine.sameClock(true,now,0,now+180000,180000));ok(!SnsScheduleEngine.sameClock(true,now,5000,now+180000,6000));ok(!SnsScheduleEngine.sameClock(true,now,5000,now-1,4000));
        ok(SnsScheduleEngine.wakeAt(now+15000,now)==now+13000);ok(SnsScheduleEngine.wakeAt(now+180000,now)==now+178000);ok(SnsScheduleEngine.wakeAt(now+1000,now)==now+50);ok(SnsScheduleEngine.wakeAt(now-1,now)==now+50);
        SnsScheduleData editing=data();ok(SnsScheduleEngine.recover(editing,now,true,true,false,Collections.singleton(id)));ok(editing.find(id).state==SnsScheduleData.State.MISSED);rejects(()->SnsScheduleEngine.claim(editing,id,now,false));SnsScheduleData editFuture=data();editFuture.find(id).due=now+1000;ok(!SnsScheduleEngine.recover(editFuture,now,true,true,false,Collections.singleton(id)));ok(editFuture.find(id).state==SnsScheduleData.State.WAITING);
        System.out.println("PASS "+checks+" scheduled Moments timer, manual recovery, durable claims, owner/media codec and duplicate guards");
    }
}
